def solve(a, x):
    """Return the leftmost index where x can be inserted into sorted list a.
    Implements bisect_left behavior.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

