    """Count the number of islands (4-directionally connected groups of 1s) in a binary grid.
    Args:
        grid (List[List[int]]): 2D list of 0s and 1s.
    Returns:
        int: Number of distinct islands.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
    visited = [[False]*m for _ in range(n)]
    def dfs(i,j):
        stack = [(i,j)]
        while stack:
            x,y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # explore neighbors
            if x>0 and grid[x-1][y]==1 and not visited[x-1][y]:
                stack.append((x-1,y))
            if x+1<n and grid[x+1][y]==1 and not visited[x+1][y]:
                stack.append((x+1,y))
            if y>0 and grid[x][y-1]==1 and not visited[x][y-1]:
                stack.append((x,y-1))
            if y+1<m and grid[x][y+1]==1 and not visited[x][y+1]:
                stack.append((x,y+1))
    islands = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j]==1 and not visited[i][j]:
                islands += 1
                dfs(i,j)
    return islands

