def solve(a, b):
    m, n = len(a), len(b)
    # use only two rows to save memory
    if m < n:
        # ensure that b is the shorter for space efficiency
        a, b = b, a
        m, n = n, m
    prev = list(range(n + 1))
    for i in range(1, m + 1):
        cur = [i] + [0] * n
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j],      # deletion
                                  cur[j - 1],   # insertion
                                  prev[j - 1])   # substitution
        prev = cur
    return prev[n]

