import heapq
def solve(n, edges):
    if n == 0:
        return -1
    adj = [[] for _ in range(n)]
    for a,b,w in edges:
        adj[a].append((b,w))
        adj[b].append((a,w))
    INF = 10**18
    dist = [INF]*n
    dist[0] = 0
    heap = [(0,0)]
    while heap:
        d,u = heapq.heappop(heap)
        if d!=dist[u]:
            continue
        if u == n-1:
            return d
        for v,w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd,v))
    return -1 if dist[-1]==INF else dist[-1]

