{"task_id": "T43", "code": "def solve(coins, amount):
    """Return the minimum number of coins needed to make up amount.
    coins: list of positive integers (coin denominations)
    amount: non‑negative integer target sum
    Returns -1 if amount cannot be formed.
    Uses classic unbounded knapsack DP with O(amount * len(coins)) time.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Initialize DP array where dp[i] = min coins to make i, INF if impossible
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue  # ignore non‑positive denominations
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1
